/// <summary>
/// 大厅/进房/离房真实 UI 验收脚本（run_script 入口）。只读服务取事实，操作一律真实射线命中 + 指针事件。
/// </summary>
public static class RunRoomFlowUi
{
    private const double ActionBudgetSeconds = 30.0;
    private const double RowWaitSeconds = 12.0;
    private const string PagePrefix = "Page_";

    /// <summary>执行一个验收动作；action 为空 = Inspect。</summary>
    public static async Task<string> Run(string action)
    {
        string normalized = (action ?? string.Empty).Trim().ToLowerInvariant();
        if (normalized.Length == 0) normalized = "inspect";

        ServiceContainer container = ResolveContainer();
        UIService ui = container.Resolve<UIService>();

        switch (normalized)
        {
            case "inspect":
                return Inspect(container, ui);
            case "login":
                return await Login(container, ui);
            case "quickenter":
                return await QuickEnter(container, ui);
            case "leave":
                return await Leave(container, ui);
            case "create":
                return await Create(container, ui);
            case "roomlist":
                return await RoomList(container, ui);
            case "cancelwait":
                return Unsupported("CancelWait",
                    "加载阻断期间用键盘 Esc 取消需要 InputSystem 设备状态事件模拟；本脚本未实现键盘驱动，未以导航/流程 API 冒充。");
            case "battlemenuleave":
                return Unsupported("BattleMenuLeave",
                    "对局菜单 Esc 入口与确认按钮的真实按键序列本脚本未实现，未以直调设置/离房 API 冒充。");
            default:
                return "action=" + action + "\nok=false\nstatus=unsupported\nreason=未知动作；已返回可诊断 Inspect。\n\n"
                       + Inspect(container, ui);
        }
    }

    private static async Task<string> Login(ServiceContainer container, UIService ui)
    {
        var deadline = new Deadline();
        var sb = Begin("Login");
        var steps = new List<string>();
        var after = new List<string>();

        string before = VisiblePages(ui);
        if (IsPageOpen(ui, PageIds.Page_Lobby))
        {
            AssertLobbyOperational(ui);
            sb.AppendLine("click=(skipped)");
            sb.AppendLine("note=Page_Lobby 已在场，无需再点登录");
            return Finish(sb, before, VisiblePages(ui), steps);
        }

        if (!IsPageOpen(ui, PageIds.Page_Login))
            throw new InvalidOperationException(
                "Login 前置不满足：Page_Login/Page_Lobby 均不可见。诊断：" + PageDiagnostics(ui));

        Button button = await WaitButtonReachable("Btn_GuestLogin", "登录页登录钮", ui, deadline);
        steps.Add("expect=Btn_GuestLogin 真实指针可点");
        ClickReport click = Click(button, "Login.Btn_GuestLogin");
        steps.Add("click=" + click.Summary);

        await WaitUntil(() => IsPageOpen(ui, PageIds.Page_Lobby), "Page_Lobby 可见", deadline,
            () => "登录后大厅未出现；" + PageDiagnostics(ui));
        steps.Add("assert=Page_Lobby IsOpen");

        await WaitUntil(() => IsLobbyOperational(ui), "大厅可操作（Btn_QuickEnter 首射线命中）", deadline,
            () => "大厅已开但入口不可点；" + LobbyDiagnostics(ui));
        steps.Add("assert=大厅可操作");

        after = SplitPages(VisiblePages(ui));
        return Finish(sb, before, string.Join(",", after.ToArray()), steps, click);
    }

    private static async Task<string> QuickEnter(ServiceContainer container, UIService ui)
    {
        var deadline = new Deadline();
        var sb = Begin("QuickEnter");
        var steps = new List<string>();

        string before = VisiblePages(ui);
        RequireLobby(ui);

        Button button = await WaitButtonReachable("Btn_QuickEnter", "大厅快速进入", ui, deadline);
        steps.Add("expect=Btn_QuickEnter 真实指针可点");
        ClickReport click = Click(button, "Lobby.Btn_QuickEnter");
        steps.Add("click=" + click.Summary);

        await WaitUntil(() => IsPageOpen(ui, PageIds.Page_Room), "Page_Room 可见", deadline,
            () => "点快速进入后房间页未出现；" + PageDiagnostics(ui));
        steps.Add("assert=Page_Room IsOpen");

        GameObject roomRoot = FindPageRoot("Page_Room");
        Button leave = await WaitButtonReachable("Btn_Leave", "房间页离房钮", ui, deadline);
        steps.Add("assert=房间页可操作（Btn_Leave 命中）");

        await WaitUntil(() => ReadRoomFacts(container, roomRoot).HasSeats, "房间投影席位非空", deadline,
            () => "房间页已开但投影无席位；" + RoomDiagnostics(container, roomRoot));
        steps.Add("assert=房间投影席位非空");

        RoomFacts room = ReadRoomFacts(container, roomRoot);
        sb.AppendLine("room=" + room.Describe());
        sb.AppendLine("join_log_hint=Unity Console: [Battle] joined (JoinAck)（排队/入场日志由流程侧打印）");

        after = VisiblePages(ui);
        return Finish(sb, before, after, steps, click);
    }

    private static async Task<string> Leave(ServiceContainer container, UIService ui)
    {
        var deadline = new Deadline();
        var sb = Begin("Leave");
        var steps = new List<string>();

        string before = VisiblePages(ui);
        if (!IsPageOpen(ui, PageIds.Page_Room))
            throw new InvalidOperationException(
                "Leave 前置不满足：Page_Room 不可见。诊断：" + PageDiagnostics(ui));

        GameObject roomRoot = FindPageRoot("Page_Room");
        sb.AppendLine("room_before=" + ReadRoomFacts(container, roomRoot).Describe());

        Button button = await WaitButtonReachable("Btn_Leave", "房间页离房钮", ui, deadline);
        steps.Add("expect=Btn_Leave 真实指针可点");
        ClickReport click = Click(button, "Room.Btn_Leave");
        steps.Add("click=" + click.Summary);

        await WaitUntil(() => IsPageOpen(ui, PageIds.Page_Lobby), "Page_Lobby 可见", deadline,
            () => "离房后大厅未出现；" + PageDiagnostics(ui));
        steps.Add("assert=Page_Lobby IsOpen");

        await WaitUntil(() => IsLobbyOperational(ui), "大厅可操作（Btn_QuickEnter 首射线命中）", deadline,
            () => "大厅已开但入口不可点；" + LobbyDiagnostics(ui));
        steps.Add("assert=大厅可操作");

        await WaitUntil(() => !IsPageOpen(ui, PageIds.Page_Room) && ReadRoomFacts(container, null).IsEmpty,
            "房间页关闭且房间投影为空", deadline,
            () => "离房后投影未清；page_room_open=" + IsPageOpen(ui, PageIds.Page_Room)
                  + ";" + RoomDiagnostics(container, FindPageRoot("Page_Room")));
        steps.Add("assert=房间页关闭且席位/期望人数清零");

        after = VisiblePages(ui);
        return Finish(sb, before, after, steps, click);
    }

    private static async Task<string> Create(ServiceContainer container, UIService ui)
    {
        var deadline = new Deadline();
        var sb = Begin("Create");
        var steps = new List<string>();

        string before = VisiblePages(ui);
        RequireLobby(ui);

        Button create = await WaitButtonReachable("Btn_CreateRoom", "大厅建房入口", ui, deadline);
        steps.Add("expect=Btn_CreateRoom 真实指针可点");
