private static string Finish(StringBuilder sb, string beforePages, string afterPages,
    List<string> steps, ClickReport click = null)
{
    sb.Insert(0, "ok=true\n");
    sb.Insert(0, "action=" + FirstValue(sb, "action=") + "\n");
    sb.Replace("action=" + FirstValue(sb, "action=") + "\nok=true\n", "action=" + FirstValue(sb, "action=") + "\nok=true\n");
    sb.AppendLine("before_pages=" + beforePages);
    sb.AppendLine("after_pages=" + afterPages);
    if (click != null)
    {
        sb.AppendLine("click_target=" + click.Target);
        sb.AppendLine("click_center=" + click.ScreenCenter);
        sb.AppendLine("click_first_hit=" + Sanitize(click.FirstHitPath));
        sb.AppendLine("click_handler=" + Sanitize(click.HandlerName));
    }
    for (int i = 0; i < steps.Count; i++) sb.AppendLine("step" + (i + 1) + "=" + steps[i]);
    return sb.ToString();
}

private static string FirstValue(StringBuilder sb, string prefix)
{
    string text = sb.ToString();
    int start = text.IndexOf(prefix, StringComparison.Ordinal);
    if (start < 0) return string.Empty;
    start += prefix.Length;
    int end = text.IndexOf('\n', start);
    return end < 0 ? text.Substring(start) : text.Substring(start, end - start);
}

