private static Button FindReachableListRow(Transform lobbyRoot, out string reason)
{
    reason = string.Empty;
    Transform list = FindChild(lobbyRoot, "VList_Rooms");
    if (list == null)
    {
        reason = "未找到 VList_Rooms 容器";
        return null;
    }

    int candidates = 0;
    foreach (Button button in list.GetComponentsInChildren<Button>(true))
    {
        if (button == null || !button.gameObject.activeInHierarchy) continue;
        candidates++;
        if (!button.IsInteractable()) continue;
        if (ProbeButton(button).Reaches) return button;
    }

    reason = "VList_Rooms 下激活 Button=" + candidates + "（0=未渲染行；>0=行被遮挡或禁用）";
    return null;
}

