private static Transform FindChildByName(string name)
{
    foreach (Transform transform in Object.FindObjectsOfType<Transform>(true))
    {
        if (transform != null && string.Equals(transform.name, name, StringComparison.Ordinal)
            && transform.gameObject.activeInHierarchy)
            return transform;
    }
    return null;
}

